def solve():
    import sys
    input_data = sys.stdin.read().split()
    idx = 0
    n = int(input_data[idx]); idx += 1

    grid = []
    for i in range(n):
        row = [int(input_data[idx+j]) for j in range(n)]
        idx += n
        grid.append(row)

    # Find empty cell
    er, ec = -1, -1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 0:
                er, ec = i, j

    if n == 1:
        print(1)
        return

    # Compute row sums (with 0 for empty cell)
    row_sums = [sum(grid[i]) for i in range(n)]
    col_sums = [sum(grid[i][j] for i in range(n)) for j in range(n)]
    diag1 = sum(grid[i][i] for i in range(n))  # main diagonal
    diag2 = sum(grid[i][n-1-i] for i in range(n))  # secondary diagonal

    # Determine S from a complete row
    S = None
    for i in range(n):
        if i != er:
            S = row_sums[i]
            break

    # x = S - row_sums[er] (since row_sums[er] has 0 instead of x)
    x = S - row_sums[er]

    if x <= 0:
        print(-1)
        return

    # Now verify: place x and check everything
    # Check all rows
    for i in range(n):
        if i == er:
            if row_sums[i] + x != S:
                print(-1)
                return
        else:
            if row_sums[i] != S:
                print(-1)
                return

    # Check all columns
    for j in range(n):
        if j == ec:
            if col_sums[j] + x != S:
                print(-1)
                return
        else:
            if col_sums[j] != S:
                print(-1)
                return

    # Check diagonals
    # Main diagonal
    if er == ec:
        if diag1 + x != S:
            print(-1)
            return
    else:
        if diag1 != S:
            print(-1)
            return

    # Secondary diagonal: position (i, n-1-i), so er == n-1-ec
    if er == n-1-ec:
        if diag2 + x != S:
            print(-1)
            return
    else:
        if diag2 != S:
            print(-1)
            return

    print(x)

