    n = int(input())
    a = []
    zr = zc = -1

    for i in range(n):
        row = list(map(int, input().split()))
        for j, v in enumerate(row):
            if v == 0:
                zr, zc = i, j
        a.append(row)

    if n == 1:
        print(1)
        return

    # Use any row different from the zero row as the target magic sum
    target = None
    for i in range(n):
        if i != zr:
            target = sum(a[i])
            break

    row_sum_with_zero = sum(a[zr])
    x = target - row_sum_with_zero

    if x <= 0:
        print(-1)
        return

    a[zr][zc] = x

    # Check all row sums
    for i in range(n):
        if sum(a[i]) != target:
            print(-1)
            return

    # Check all column sums
    for j in range(n):
        s = 0
        for i in range(n):
            s += a[i][j]
        if s != target:
            print(-1)
            return

    # Check diagonals
    s1 = 0
    s2 = 0
    for i in range(n):
        s1 += a[i][i]
        s2 += a[i][n - 1 - i]

    if s1 != target or s2 != target:
        print(-1)
        return

    print(x)

